/**
 * Minimal MSAL v1 compatible wrapper for Chrome 42 / Android 4.4
 * Uses OAuth2 implicit flow with Microsoft Identity Platform
 * Compatible with ES5 / Chrome 42+
 *
 * v1.3 — complete rewrite of token renewal:
 *  - acquireTokenSilent now does hidden iframe renewal (like real MSAL)
 *  - _processRedirectIfRequired detects iframe context → postMessage to parent
 *  - loginRedirect honours request.prompt and request.loginHint
 *  - clearCache() and getAllAccounts() for index.html doReauth() compatibility
 */
var Msal = (function() {

  function UserAgentApplication(config) {
    this.clientId = config.auth.clientId;
    this.authority = config.auth.authority || 'https://login.microsoftonline.com/common';
    this.redirectUri = config.auth.redirectUri || window.location.href;
    this.cacheLocation = (config.cache && config.cache.cacheLocation) || 'localStorage';
    this.storeAuthStateInCookie = (config.cache && config.cache.storeAuthStateInCookie) || false;
    this._redirectCallback = null;
    this._storage = window[this.cacheLocation] || window.localStorage;
    this._iframeRenewalInProgress = false;
    this._processRedirectIfRequired();
  }

  // ── Storage helpers ──

  UserAgentApplication.prototype._key = function(k) {
    return 'msal.' + this.clientId + '.' + k;
  };

  UserAgentApplication.prototype._save = function(k, v) {
    try { this._storage.setItem(this._key(k), v); } catch(e) {}
  };

  UserAgentApplication.prototype._load = function(k) {
    try { return this._storage.getItem(this._key(k)) || null; } catch(e) { return null; }
  };

  UserAgentApplication.prototype._del = function(k) {
    try { this._storage.removeItem(this._key(k)); } catch(e) {}
  };

  // ── Redirect hash processing ──
  // Called in constructor. Handles the token that Azure returns in the URL hash.
  // KEY: If running inside a hidden iframe (silent renewal), posts the hash
  // to the parent window via postMessage instead of processing it locally.

  UserAgentApplication.prototype._processRedirectIfRequired = function() {
    var self = this;
    var hash = window.location.hash;
    if (!hash || (hash.indexOf('access_token') === -1 && hash.indexOf('error') === -1)) return;

    // ── IFRAME DETECTION ──
    // If we're inside a hidden iframe (silent renewal), post the raw hash
    // to the parent window and stop. Parent's _renewViaIframe listener handles it.
    try {
      if (window !== window.top) {
        window.parent.postMessage({
          type: 'msal_iframe_result',
          hash: hash
        }, window.location.origin);
        // Clear hash so the iframe doesn't reprocess
        try { window.history.replaceState({}, document.title, window.location.pathname + window.location.search); } catch(e) { window.location.hash = ''; }
        return;
      }
    } catch(e) {
      // Cross-origin parent — not our iframe, process normally
    }

    // ── NORMAL (top-level) redirect processing ──
    try {
      var params = {};
      var parts = hash.replace('#', '').split('&');
      for (var i = 0; i < parts.length; i++) {
        var kv = parts[i].split('=');
        if (kv.length === 2) params[decodeURIComponent(kv[0])] = decodeURIComponent(kv[1]);
      }

      if (params.error) {
        var err = { errorCode: params.error, errorMessage: params.error_description || params.error };
        try { window.history.replaceState({}, document.title, window.location.pathname + window.location.search); } catch(e) { window.location.hash = ''; }
        if (self._redirectCallback) self._redirectCallback(err, null);
        return;
      }

      if (params.access_token) {
        var expiresIn = parseInt(params.expires_in || '3600');
        var expiresAt = Math.floor(Date.now() / 1000) + expiresIn;

        self._save('access_token', params.access_token);
        self._save('token_expires', String(expiresAt));
        self._save('id_token', params.id_token || '');

        var account = self._parseIdToken(params.id_token || '');
        if (account) {
          self._save('account', JSON.stringify(account));
        }

        try { window.history.replaceState({}, document.title, window.location.pathname + window.location.search); } catch(e) { window.location.hash = ''; }

        var resp = { accessToken: params.access_token, account: account, expiresOn: new Date(expiresAt * 1000) };
        if (self._redirectCallback) {
          setTimeout(function() { self._redirectCallback(null, resp); }, 100);
        }
      }
    } catch(e) {
      if (self._redirectCallback) self._redirectCallback({ errorMessage: String(e) }, null);
    }
  };

  UserAgentApplication.prototype._parseIdToken = function(idToken) {
    if (!idToken) return { name: 'User', userName: '' };
    try {
      var parts = idToken.split('.');
      if (parts.length < 2) return { name: 'User', userName: '' };
      var payload = parts[1];
      while (payload.length % 4) payload += '=';
      payload = payload.replace(/-/g, '+').replace(/_/g, '/');
      var decoded = JSON.parse(atob(payload));
      return {
        name: decoded.name || decoded.preferred_username || 'User',
        userName: decoded.preferred_username || decoded.upn || decoded.email || '',
        homeAccountId: decoded.oid || '',
        environment: 'login.microsoftonline.com',
        tenantId: decoded.tid || ''
      };
    } catch(e) {
      return { name: 'User', userName: '' };
    }
  };

  // ── Public API ──

  UserAgentApplication.prototype.handleRedirectCallback = function(callback) {
    this._redirectCallback = callback;
  };

  UserAgentApplication.prototype.getAccount = function() {
    try {
      var acct = this._load('account');
      if (!acct) return null;
      return JSON.parse(acct);
    } catch(e) { return null; }
  };

  UserAgentApplication.prototype.getAllAccounts = function() {
    var acct = this.getAccount();
    return acct ? [acct] : [];
  };

  UserAgentApplication.prototype.clearCache = function() {
    this._del('access_token');
    this._del('token_expires');
    this._del('id_token');
    this._del('account');
    this._del('login_state');
    this._del('nonce');
  };

  // ── loginRedirect ──
  // Honours request.prompt and request.loginHint (v1.2 fix)

  UserAgentApplication.prototype.loginRedirect = function(request) {
    var scopes = (request && request.scopes) || [];
    var prompt = (request && request.prompt) || 'select_account';
    var loginHint = (request && request.loginHint) || '';

    var state = 'login_' + Math.random().toString(36).substr(2, 9);
    var nonce = Math.random().toString(36).substr(2, 16);
    this._save('login_state', state);
    this._save('nonce', nonce);

    var url = this.authority + '/oauth2/v2.0/authorize' +
      '?client_id=' + encodeURIComponent(this.clientId) +
      '&response_type=token+id_token' +
      '&redirect_uri=' + encodeURIComponent(this.redirectUri) +
      '&scope=' + encodeURIComponent(scopes.join(' ') + ' openid profile') +
      '&response_mode=fragment' +
      '&state=' + encodeURIComponent(state) +
      '&nonce=' + encodeURIComponent(nonce) +
      '&prompt=' + encodeURIComponent(prompt);

    if (loginHint) {
      url += '&login_hint=' + encodeURIComponent(loginHint);
    }

    window.location.href = url;
  };

  // ── acquireTokenSilent ──
  // 1. Check cached token in localStorage
  // 2. If expired → try hidden iframe renewal with prompt=none
  // 3. If iframe fails → reject (caller falls back to interactive redirect)

  UserAgentApplication.prototype.acquireTokenSilent = function(request) {
    var self = this;
    return new Promise(function(resolve, reject) {
      try {
        var token = self._load('access_token');
        var expires = parseInt(self._load('token_expires') || '0');
        var now = Math.floor(Date.now() / 1000);

        // Token still valid (with 5-minute buffer)
        if (token && expires > now + 300) {
          resolve({ accessToken: token, expiresOn: new Date(expires * 1000) });
          return;
        }

        // Token expired or near-expiry — try iframe renewal
        self._renewViaIframe(request).then(function(resp) {
          resolve(resp);
        }).catch(function(iframeErr) {
          // Iframe failed — clean up and reject
          self._del('access_token');
          self._del('token_expires');
          reject(new Error('Token expired, silent renewal failed: ' + (iframeErr.message || iframeErr)));
        });
      } catch(e) {
        reject(e);
      }
    });
  };

  // ── Hidden iframe renewal ──
  // Creates a hidden iframe, navigates to Azure AD with prompt=none,
  // waits for the iframe to redirect back with a new token in the hash.
  // The iframe's _processRedirectIfRequired detects iframe context and
  // postMessages the hash to us.
  //
  // This is the same mechanism the real MSAL library uses for silent renewal.

  UserAgentApplication.prototype._renewViaIframe = function(request) {
    var self = this;

    // Deduplicate — only one iframe renewal at a time
    if (self._iframeRenewalInProgress) {
      return new Promise(function(resolve, reject) {
        reject(new Error('Iframe renewal already in progress'));
      });
    }

    var scopes = (request && request.scopes) || [];
    var loginHint = (request && request.loginHint) || '';

    // Try to get loginHint from saved sources if not provided
    if (!loginHint) {
      try { loginHint = localStorage.getItem('roomdisplay_loginhint') || ''; } catch(e) {}
    }
    if (!loginHint) {
      var acct = self.getAccount();
      if (acct) loginHint = acct.userName || '';
    }

    return new Promise(function(resolve, reject) {
      self._iframeRenewalInProgress = true;

      var timeout, listener;
      var iframe = document.createElement('iframe');
      iframe.style.cssText = 'position:absolute;width:0;height:0;border:none;visibility:hidden;';
      iframe.setAttribute('aria-hidden', 'true');

      function cleanup() {
        self._iframeRenewalInProgress = false;
        clearTimeout(timeout);
        try { window.removeEventListener('message', listener); } catch(e) {}
        try { document.body.removeChild(iframe); } catch(e) {}
      }

      // Listen for postMessage from the iframe
      listener = function(e) {
        // Security: only accept messages from our own origin
        if (e.origin !== window.location.origin) return;
        if (!e.data || e.data.type !== 'msal_iframe_result') return;

        var hash = e.data.hash || '';

        // Parse the hash
        var params = {};
        var parts = hash.replace('#', '').split('&');
        for (var i = 0; i < parts.length; i++) {
          var kv = parts[i].split('=');
          if (kv.length === 2) params[decodeURIComponent(kv[0])] = decodeURIComponent(kv[1]);
        }

        // Check for error (interaction_required = session expired, need interactive login)
        if (params.error) {
          cleanup();
          reject(new Error(params.error_description || params.error));
          return;
        }

        // Got a token!
        if (params.access_token) {
          var expiresIn = parseInt(params.expires_in || '3600');
          var expiresAt = Math.floor(Date.now() / 1000) + expiresIn;

          self._save('access_token', params.access_token);
          self._save('token_expires', String(expiresAt));
          if (params.id_token) self._save('id_token', params.id_token);

          // Update account from new id_token
          var account = self._parseIdToken(params.id_token || '');
          if (account && account.userName) {
            self._save('account', JSON.stringify(account));
          }

          cleanup();
          resolve({ accessToken: params.access_token, expiresOn: new Date(expiresAt * 1000) });
          return;
        }

        // Hash had neither token nor error — shouldn't happen
        cleanup();
        reject(new Error('Unexpected iframe response'));
      };

      window.addEventListener('message', listener);

      // Timeout: if no response within 15 seconds, iframe renewal failed
      // (Azure session expired, cookies blocked, network issue, etc.)
      timeout = setTimeout(function() {
        cleanup();
        reject(new Error('Iframe renewal timeout'));
      }, 15000);

      // Build the authorize URL with prompt=none
      var state = 'silent_' + Math.random().toString(36).substr(2, 9);
      var nonce = Math.random().toString(36).substr(2, 16);

      var url = self.authority + '/oauth2/v2.0/authorize' +
        '?client_id=' + encodeURIComponent(self.clientId) +
        '&response_type=token+id_token' +
        '&redirect_uri=' + encodeURIComponent(self.redirectUri) +
        '&scope=' + encodeURIComponent(scopes.join(' ') + ' openid profile') +
        '&response_mode=fragment' +
        '&state=' + encodeURIComponent(state) +
        '&nonce=' + encodeURIComponent(nonce) +
        '&prompt=none';

      if (loginHint) {
        url += '&login_hint=' + encodeURIComponent(loginHint);
      }

      // Launch the iframe
      document.body.appendChild(iframe);
      iframe.src = url;
    });
  };

  UserAgentApplication.prototype.acquireTokenRedirect = function(request) {
    this.loginRedirect(request);
  };

  UserAgentApplication.prototype.logout = function() {
    this._del('access_token');
    this._del('token_expires');
    this._del('id_token');
    this._del('account');
    var url = this.authority + '/oauth2/v2.0/logout?post_logout_redirect_uri=' +
      encodeURIComponent(this.redirectUri);
    window.location.href = url;
  };

  return { UserAgentApplication: UserAgentApplication };
})();
